<script lang="ts">
 import {onDestroy,untrack} from 'svelte';
 import type {AccountProfilesGateway,PublicProfile} from '../application/account-profiles';
 import type {Account} from '$lib/features/identity/domain/account';
 import {useLocale,text} from '$lib/shared/presentation/locale';
 import {failureCode} from '$lib/shared/presentation/copy';
 import {page} from '$app/state';
 import ActionLink from '$lib/shared/presentation/ui/ActionLink.svelte';
 import Button from '$lib/shared/presentation/ui/Button.svelte';
 let {id,user,gateway}:{id:string;user:Account|null;gateway:AccountProfilesGateway}=$props();
 const {locale}=useLocale();
 let request=0;
 let failedAvatar=$state('');
 let profile=$state<PublicProfile|null>(null),error=$state(''),busy=$state(false),shared=$state(false);
 const statusNames=$derived<Record<string,string>>({reading:text($locale,'Қазір оқып жүр','Сейчас читает'),planned:text($locale,'Оқу жоспары','Планы чтения'),completed:text($locale,'Оқып бітірген','Прочитано'),paused:text($locale,'Үзілісте','На паузе'),dropped:text($locale,'Тоқтатылған','Брошено')});
 let tab=$derived(page.url.searchParams.get('tab')||'library');
 function current(sequence:number,target:string,actor:string|undefined){return sequence===request&&id===target&&user?.id===actor;}
 async function load(){const sequence=++request,target=id,actor=user?.id;profile=null;error='';busy=false;shared=false;try{const loaded=await gateway.profile(target);if(current(sequence,target,actor))profile=loaded;}catch(e){if(!current(sequence,target,actor))return;error=failureCode(e)==='profile_not_found'?text($locale,'Профиль табылмады немесе жеке.','Профиль не найден или закрыт.'):text($locale,'Профиль жүктелмеді.','Не удалось загрузить профиль.');}}
 $effect(()=>{id;user?.id;untrack(()=>void load());});
 onDestroy(()=>{request++;});
 async function follow(){if(!user||!profile||busy)return;const sequence=request,target=id,actor=user.id,following=!profile.is_following;busy=true;error='';try{await gateway.follow(actor,target,following);if(!current(sequence,target,actor))return;const loaded=await gateway.profile(target);if(current(sequence,target,actor))profile=loaded;}catch{if(current(sequence,target,actor))error=text($locale,'Жазылу өзгермеді. Қайта көріңіз.','Не удалось изменить подписку. Повторите.');}finally{if(current(sequence,target,actor))busy=false;}}
 async function share(){try{await navigator.clipboard.writeText(window.location.origin+'/users/'+encodeURIComponent(id));shared=true;}catch{error=text($locale,'Сілтемені мекенжай жолағынан көшіріңіз.','Скопируйте ссылку из адресной строки.');}}
</script>
<svelte:head><title>{profile?.display_name||text($locale,'Профиль','Профиль')} — Qmanga</title><meta name="robots" content="noindex"/></svelte:head>
{#if error}<p role="alert" class="error">{error}</p>{#if !profile}<Button onclick={load}>{text($locale,'Қайта көру','Повторить')}</Button>{/if}{/if}
{#if profile}<article class="profile"><div class="banner" aria-hidden="true"><span>Qmanga</span></div><header class="identity"><div class="avatar">{#if profile.avatar_url&&failedAvatar!==profile.avatar_url}<img src={profile.avatar_url} alt="" onerror={()=>failedAvatar=profile?.avatar_url||''}/>{:else}{profile.display_name.slice(0,1).toUpperCase()}{/if}</div><div class="name"><h1>{profile.display_name}</h1>{#if profile.created_at}<p class="muted">{text($locale,'Қосылған күні','Присоединился')} · {new Date(profile.created_at).toLocaleDateString($locale==='kk'?'kk-KZ':'ru-RU',{month:'long',year:'numeric'})}</p>{/if}<div class="actions">{#if profile.is_owner}<ActionLink href="/settings?section=account">{text($locale,'Профильді өзгерту','Редактировать профиль')}</ActionLink>{:else if profile.allow_follow||profile.is_following}{#if user}<Button {busy} onclick={follow}>{profile.is_following?text($locale,'Жазылымнан шығу','Отписаться'):text($locale,'Жазылу','Подписаться')}</Button>{:else}<ActionLink href={'/login?returnTo='+encodeURIComponent('/users/'+id)}>{text($locale,'Жазылу','Подписаться')}</ActionLink>{/if}{/if}<Button variant="ghost" onclick={share}>{shared?text($locale,'Көшірілді','Скопировано'):text($locale,'Бөлісу','Поделиться')}</Button></div></div></header>
{#if profile.bio}<p class="bio">{profile.bio}</p>{/if}<p class="counts">{profile.followers_count} {text($locale,'жазылушы','подписчиков')} <span>·</span> {profile.following_count} {text($locale,'жазылым','подписок')}</p><p class="muted">{profile.public_profile?text($locale,'Жария профиль','Публичный профиль'):text($locale,'Жеке профиль — тек сізге көрінеді','Закрытый профиль — виден только вам')}</p>
<nav class="tabs" aria-label={text($locale,'Профиль бөлімдері','Разделы профиля')}>{#each [['library','Оқу сөресі','Библиотека'],['activity','Белсенділік','Активность'],['about','Мен туралы','О себе']] as item}<a href={'?tab='+item[0]} aria-current={tab===item[0]?'page':undefined}>{text($locale,item[1],item[2])}</a>{/each}</nav>
{#if tab==='library'}{#if !profile.show_library}<p class="empty">{text($locale,'Оқу тізімі жасырылған.','Библиотека скрыта.')}</p>{:else if !profile.library.length}<p class="empty">{text($locale,'Оқу тізімі бос.','Библиотека пока пуста.')}</p>{:else}<div class="shelf-groups">{#each [...new Set(['reading','planned','completed','paused','dropped',...profile.library.map(title=>title.status)])] as status}{@const entries=profile.library.filter(title=>title.status===status)}{#if entries.length}<section class="shelf-group"><h2>{statusNames[status]||text($locale,'Кітапханадағы тайтлдар','Тайтлы в библиотеке')}</h2><div class="shelf">{#each entries as title}<a class="book" href={'/titles/'+encodeURIComponent(title.slug)}>{#if title.cover_url}<img src={title.cover_url} alt="" loading="lazy"/>{/if}<div><h3>{title.name}</h3>{#if title.progress!==undefined}<p class="muted">{text($locale,'Оқу орны','Прогресс')}: {title.progress}</p>{/if}</div></a>{/each}</div></section>{/if}{/each}</div>{/if}
{:else if tab==='activity'}{#if !profile.show_activity}<p class="empty">{text($locale,'Белсенділік жасырылған.','Активность скрыта.')}</p>{:else if !profile.activity.length}<p class="empty">{text($locale,'Белсенділік әзірше жоқ.','Активности пока нет.')}</p>{:else}<ul class="activity">{#each profile.activity as item}<li>{#if item.href.startsWith('/')&&!item.href.startsWith('//')}<a href={item.href}>{item.label}</a>{:else}<span>{item.label}</span>{/if}<time datetime={item.created_at}>{new Date(item.created_at).toLocaleDateString($locale==='kk'?'kk-KZ':'ru-RU')}</time></li>{/each}</ul>{/if}
{:else}<p class="bio">{profile.bio||text($locale,'Әзірше сипаттама жоқ.','Описание пока не добавлено.')}</p>{/if}</article>{:else if !error}<p class="muted">{text($locale,'Жүктелуде…','Загрузка…')}</p>{/if}
<style>.profile{max-width:880px;margin:auto}.banner{height:150px;background:var(--panel);border:1px solid var(--line);border-bottom:3px solid var(--accent);border-radius:10px 10px 0 0;display:flex;align-items:center;justify-content:flex-end;padding:32px;color:var(--muted)}.banner span{font-size:22px;font-weight:800;opacity:.5}.identity{display:flex;align-items:start;gap:20px;margin: -25px 20px 24px}.avatar{width:88px;height:88px;flex-shrink:0;border:4px solid var(--bg);border-radius:50%;display:grid;place-items:center;background:var(--accent);color:#171014;font-size:32px;font-weight:750;overflow:hidden}.avatar img{width:100%;height:100%;object-fit:cover}.name{padding-top:32px;min-width:0}.name h1{overflow-wrap:anywhere;font-size:24px}.name p{font-size:12px;margin:5px 0 12px}.actions{display:flex;gap:8px;flex-wrap:wrap}.bio{white-space:pre-wrap;overflow-wrap:anywhere;margin:24px 0;max-width:650px}.counts{display:flex;gap:12px;margin-bottom:10px;font-size:14px}.tabs{display:flex;border-bottom:1px solid var(--line);gap:20px;margin:28px 0 24px}.tabs a{min-height:44px;display:flex;align-items:center;font-size:14px;color:var(--muted);border-bottom:2px solid transparent}.tabs a[aria-current]{color:var(--text);border-color:var(--accent)}.shelf{display:grid;grid-template-columns:repeat(auto-fit,minmax(240px,1fr));gap:12px}.book{display:flex;gap:14px;padding:14px;border:1px solid var(--line);border-radius:8px;background:var(--panel)}.book img{width:64px;height:90px;object-fit:cover;border-radius:4px}.book h3{font-size:15px}.shelf-group>h2{font-size:16px;margin-bottom:14px}.shelf-groups{display:grid;gap:28px}.book p{font-size:12px;margin-top:8px}.empty{padding:28px 0;color:var(--muted)}.activity{list-style:none;padding:0}.activity li{min-height:64px;display:flex;justify-content:space-between;align-items:center;gap:16px;border-bottom:1px solid var(--line)}time{font-size:12px;color:var(--muted)}@media(max-width:480px){.banner{height:120px}.identity{margin-left:0;gap:10px}.avatar{width:68px;height:68px}.name h1{font-size:20px}.tabs{gap:16px}.tabs a{font-size:12px}.counts{font-size:12px}.shelf{grid-template-columns:1fr}}
</style>
